  focusFoe(s,i);
  if(b.enemyBurn>0){const n=b.enemyBurn;b.enemyHp=Math.max(0,b.enemyHp-n);b.enemyBurn--;log(s,`燃烧：${ENEMIES[b.enemy].name} 防线 -${n}（剩余 ${b.enemyHp}）。`);if(!b.enemyHp){if(!foeDown(s)){win(s);return;}continue;}checkEnemyHpTraits(s);}
