 if(nb&&Object.keys(nb.roleCounts||{}).length>=5)f.flags.cn5=true;
 if((nb?.rt?.temps||0)>=10)f.flags.pac10=true;
 if(nc&&ctx.next.inCombat&&nc.block>=40&&nc.enemies.some(e=>e.hp>0&&e.weak>0))f.flags.emea40=true;
